  const [isSyncing, setIsSyncing] = useState(false); 
  const fileInputRef = useRef<HTMLInputElement>(null);
  const adImageInputRef = useRef<HTMLInputElement>(null);

  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  // Color Management State
  const [showColorModal, setShowColorModal] = useState(false);
  const [colorContext, setColorContext] = useState<'lipstick' | 'blush' | 'hair'>('lipstick');
  const [editingColor, setEditingColor] = useState<any | null>(null);
  const [tempColor, setTempColor] = useState({ id: '', label: '', hex: '#000000' });

  useEffect(() => {
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    setIsSyncing(true);
    setSaveStatus('Đang kết nối Cloud...');

    if (!form.googleScriptUrl || !form.googleScriptUrl.startsWith('https://script.google.com')) {
        setIsSyncing(false);
        setSaveStatus('Lỗi URL');
        alert("Lỗi: URL Google Script không hợp lệ.");
        return;
    }

    saveConfig(form);
    onUpdateConfig(form);

    try {
        const success = await saveAppConfigToCloud(form);
        if (success) setSaveStatus('✔ Đã đồng bộ Cloud');
        else {
            setSaveStatus('⚠️ Đã lưu máy (Lỗi Cloud)');
            alert("Lưu cục bộ thành công nhưng lỗi đồng bộ Cloud.");
        }
    } catch (e) {
        setSaveStatus('❌ Lỗi mạng');
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 5000);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { alert("Ảnh quá lớn!"); return; }
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, logoUrl: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const handleAdImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { alert("Ảnh quá lớn (Tối đa 2MB)!"); return; }
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, customContentImageUrl: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveLogo = () => {
    setForm(prev => ({ ...prev, logoUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRemoveAdImage = () => {
    setForm(prev => ({ ...prev, customContentImageUrl: '' }));
    if (adImageInputRef.current) adImageInputRef.current.value = '';
  };

