import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema cho phản hồi phân tích camera AI
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Phân tích frame webcam để kiểm tra độ tuân thủ ảnh thẻ bằng Gemini 3 Flash.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Phân tích ảnh thẻ sinh trắc học. Trả về JSON.
            Tiêu chí: Mặt nhìn thẳng, mắt mở, miệng đóng, đủ sáng, không bóng đổ mạnh.
            JSON: {isCompliant: boolean, status: 'VALID'|'ADJUSTING'|'INVALID', feedback: string, instruction: string, faceDetected: boolean}.
            'instruction': Câu lệnh tiếng Việt ngắn gọn (VD: "Nâng cằm lên", "Nhìn thẳng camera").` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Sẵn sàng', 
      faceDetected: true 
    };
  }
};

/**
 * Xử lý ảnh thẻ bằng AI với các tham số kỹ thuật (Intensity Factors).
 * BẮT BUỘC GIỮ NGUYÊN ĐẶC ĐIỂM SINH TRẮC HỌC.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Xây dựng prompt có cấu trúc Deterministic (Nếu Intensity = 0 thì bỏ qua)
  const systemInstructions = [
    "Bạn là chuyên gia chỉnh sửa ảnh thẻ chuyên nghiệp. Thực hiện các thay đổi dựa trên các tham số cường độ (Intensity) từ 0-100.",
    "",
    "### QUY TẮC SINH TRẮC HỌC TUYỆT ĐỐI:",
    "- CẤM THAY ĐỔI cấu trúc xương mặt, hốc mắt, hình dáng mũi và cằm.",
    "- CẤM XÓA nốt ruồi, sẹo, hoặc các đặc điểm định danh vĩnh viễn.",
    "- Duy trì tính nhất quán về ánh sáng giữa khuôn mặt và phông nền mới.",
    "",
    "### CHỈ THỊ CHI TIẾT (DETERMINISTIC):",
    `1. [Thay Phông Nền]: ${bgType.toUpperCase()}`,
    bgType === BackgroundType.WHITE ? "- Hành động: Thay toàn bộ phông nền bằng màu trắng (#FFFFFF)." : 
    bgType === BackgroundType.BLUE ? "- Hành động: Thay toàn bộ phông nền bằng màu xanh chuẩn (#2792ff)." :
    bgType === BackgroundType.GRAY ? "- Hành động: Thay toàn bộ phông nền bằng màu xám (#d1d5db)." :
    "- Hành động: BỎ QUA tác vụ này, giữ nguyên nền gốc.",
    "",
    `2. [Thay Trang Phục]: ${clothingPrompt ? `Intensity: 100, Item: ${clothingPrompt}` : 'Intensity: 0'}`,
    clothingPrompt ? `- Hành động: Thay trang phục thành "${clothingPrompt}". Đảm bảo cổ áo khít tự nhiên.` : "- Hành động: BỎ QUA tác vụ này.",
    "",
    `3. [Làm Mịn Da]: Intensity ${beautySettings.smoothSkin}/100`,
    beautySettings.smoothSkin === 0 ? "- Hành động: BỎ QUA hoàn toàn, không can thiệp vào da." : `- Hành động: Làm mịn da ở mức ${beautySettings.smoothSkin}%. Giữ lại vân da tự nhiên.`,
    "",
    `4. [Xóa Khuyết Điểm]: ${beautySettings.removeBlemishes ? 'Intensity: 100' : 'Intensity: 0'}`,
    beautySettings.removeBlemishes ? "- Hành động: Xóa các đốm mụn tạm thời. GIỮ LẠI nốt ruồi và sẹo." : "- Hành động: BỎ QUA tác vụ này.",
    "",
    `5. [Son Môi]: Màu "${beautySettings.lipstickColor}", Intensity ${beautySettings.lipstickIntensity}/100`,
    beautySettings.lipstickIntensity === 0 ? "- Hành động: BỎ QUA, không thêm màu môi." : `- Hành động: Áp dụng màu ${beautySettings.lipstickColor} với cường độ ${beautySettings.lipstickIntensity}%.`,
    "",
    `6. [Má Hồng]: Màu "${beautySettings.blushColor}", Intensity ${beautySettings.blushIntensity}/100`,
    beautySettings.blushIntensity === 0 ? "- Hành động: BỎ QUA, không thêm má hồng." : `- Hành động: Áp dụng màu má hồng ${beautySettings.blushColor} với cường độ ${beautySettings.blushIntensity}%.`,
    "",
    `7. [Tạo Khối]: Intensity ${beautySettings.contourIntensity}/100`,
    beautySettings.contourIntensity === 0 ? "- Hành động: BỎ QUA, không thay đổi khối khuôn mặt." : `- Hành động: Nhấn nhẹ khối ở mức ${beautySettings.contourIntensity}%.`,
    "",
    `8. [Chân Mày]: Intensity ${beautySettings.eyebrowIntensity}/100`,
    beautySettings.eyebrowIntensity === 0 ? "- Hành động: BỎ QUA, giữ nguyên chân mày." : `- Hành động: Định hình chân mày ở mức ${beautySettings.eyebrowIntensity}%.`,
    "",
    `9. [Làm Dày Tóc & Đổi Màu]: Intensity ${beautySettings.hairVolume}/100, Màu: ${beautySettings.hairColor || 'Màu gốc'}`,
    beautySettings.hairVolume === 0 ? "- Hành động: BỎ QUA, không can thiệp tóc." : `- Hành động: Làm dày và gọn tóc ở mức ${beautySettings.hairVolume}%, nhuộm màu tóc sang "${beautySettings.hairColor}".`,
    "",
    "KẾT QUẢ: Chỉ trả về dữ liệu ảnh JPEG chất lượng cao (Base64)."
  ].join("\n");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: systemInstructions }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("AI không trả về dữ liệu ảnh.");

  } catch (error: any) {
    console.error("Gemini processing error:", error);
    if (error.status === 429 || JSON.stringify(error).includes('429')) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }
    throw error;
  }
};

import React, { useState } from 'react';
import StartScreen from './StartScreen';
import CameraCapture from './CameraCapture';
import ImageEditor from './ImageEditor';
import PrintPreview from './PrintPreview';
import { AppStep, BackgroundType, PhotoSettings, PhotoSize, SavedPhoto, AppConfig, SkinToneType } from '../types';

interface PhotoBoothProps {
  onSaveToGallery?: () => void;
  initialPhoto?: SavedPhoto | null;
  onHome: () => void;
  config: AppConfig;
}

const PhotoBooth: React.FC<PhotoBoothProps> = ({ onSaveToGallery, initialPhoto, onHome, config }) => {
  // If loading from gallery, skip config and capture, go to print
  const [step, setStep] = useState<AppStep>(initialPhoto ? AppStep.PRINT : AppStep.CONFIG);

  // Data State
  const [capturedImage, setCapturedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');
  const [processedImage, setProcessedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');

  // Settings State
  const [settings, setSettings] = useState<PhotoSettings>(initialPhoto ? initialPhoto.settings : {
    size: PhotoSize.SIZE_4X6, // Default
    background: BackgroundType.WHITE,
    clothingPrompt: undefined,
    beauty: {
      smoothSkin: 0,
      removeBlemishes: false,

      // Hair defaults
      hairVolume: 0,
      hairStyle: 'original',

      makeupStyle: 'natural',

      skinToneType: SkinToneType.NATURAL,
      skinToneIntensity: 0,

      lighting: 0,
      contrast: 0,

      lipstickColor: 'pink',
      lipstickIntensity: 0,
      // Fix: Added missing blushColor property required by BeautySettings interface
      blushColor: 'pink',
      eyebrowIntensity: 0,
      contourIntensity: 0,
      blushIntensity: 0
    },
    printQuantity: 4,
    phoneNumber: config.contactZalo // Default phone from config
  });

  const handleStartConfig = (config: { size: PhotoSize; background: BackgroundType; quantity: number }) => {
    setSettings({
      ...settings,
      size: config.size,
      background: config.background,
      printQuantity: config.quantity
    });
    setStep(AppStep.CAPTURE);
  };

  const handleCapture = (imageSrc: string) => {
    setCapturedImage(imageSrc);
    setStep(AppStep.EDIT);
  };

  const handleProcessedImage = (img: string) => {
    setProcessedImage(img);
  };

  const resetFlow = () => {
    setCapturedImage('');
    setProcessedImage('');
    setStep(AppStep.CONFIG); 
  };

  const handleRetake = () => {
    setCapturedImage('');
    setStep(AppStep.CAPTURE);
  };

  return (
    <div className="h-full w-full">
      {step === AppStep.CONFIG && (
        <StartScreen 
          onStart={handleStartConfig} 
          onHome={onHome} 
          config={config} 
        />
      )}

      {step === AppStep.CAPTURE && (
        <CameraCapture 
          onCapture={handleCapture}
          selectedSize={settings.size}
          onSizeChange={(s) => setSettings({...settings, size: s})}
        />
      )}

      {step === AppStep.EDIT && (
        <ImageEditor 
          originalImage={capturedImage}
          settings={settings}
          onUpdateSettings={setSettings}
          onProcessedImage={handleProcessedImage}
          onNext={() => setStep(AppStep.PRINT)}
          onRetake={handleRetake}
          config={config}
        />
      )}

      {step === AppStep.PRINT && (
        <PrintPreview 
          processedImage={processedImage}
          size={settings.size}
          settings={settings}
          onBack={() => setStep(AppStep.EDIT)}
          onNew={resetFlow}
          onSaved={onSaveToGallery}
          onHome={onHome}
          config={config}
        />
      )}
    </div>
  );
};

