const AdminRulesTab: React.FC<AdminRulesTabProps> = ({ form, setForm }) => {
  const handleRuleChange = (size: string, index: number, value: string) => {
    const newRules = { ...form.photoRules };
    newRules[size][index] = value;
    setForm(prev => ({ ...prev, photoRules: newRules }));
  };

  const addRule = (size: string) => {
    const newRules = { ...form.photoRules };
    newRules[size] = [...(newRules[size] || []), 'Quy định mới...'];
    setForm(prev => ({ ...prev, photoRules: newRules }));
  };

  const removeRule = (size: string, index: number) => {
    const newRules = { ...form.photoRules };
    newRules[size].splice(index, 1);
    setForm(prev => ({ ...prev, photoRules: newRules }));
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {Object.values(PhotoSize).map(size => (
        <div key={size} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex justify-between items-center mb-4 border-b pb-2">
            <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">Quy định ảnh {size}</h3>
            <button onClick={() => addRule(size)} className="text-xs bg-brand-50 text-brand-600 px-3 py-1.5 rounded-lg font-bold hover:bg-brand-100">+ Thêm quy định</button>
          </div>
          <div className="space-y-3">
            {form.photoRules[size]?.map((rule, idx) => (
              <div key={idx} className="flex gap-2">
                <input 
                  type="text" 
                  value={rule} 
                  onChange={(e) => handleRuleChange(size, idx, e.target.value)} 
                  className={`${baseInputClass} text-sm py-2`} 
                />
                <button onClick={() => removeRule(size, idx)} className="text-red-400 hover:text-red-600 px-2">✕</button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default AdminRulesTab;

import React, { useState } from 'react';
import { AppConfig, ClothingItem } from '../types';
import { InputGroup, baseInputClass } from './AdminShared';

interface AdminClothingTabProps {
  form: AppConfig;
  setForm: React.Dispatch<React.SetStateAction<AppConfig>>;
}

const AdminClothingTab: React.FC<AdminClothingTabProps> = ({ form, setForm }) => {
  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  const openAddClothing = () => {
    setEditingItem(null);
    setTempClothing({ id: `custom_${Date.now()}`, label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-blue-500' });
    setShowClothingModal(true);
  };

  const openEditClothing = (item: ClothingItem) => {
    setEditingItem(item);
    setTempClothing({ ...item });
    setShowClothingModal(true);
  };

  const saveClothingItem = () => {
    let newOptions = [...form.clothingOptions];
    if (editingItem) newOptions = newOptions.map(item => item.id === editingItem.id ? tempClothing : item);
    else newOptions.push(tempClothing);
    setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    setShowClothingModal(false);
