      {showClothingModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl animate-fadeIn">
              <h3 className="text-xl font-bold mb-6">{editingItem ? 'Sửa' : 'Thêm'} trang phục</h3>
              <div className="space-y-4">
                 <InputGroup label="Tên nhãn"><input type="text" className={baseInputClass} value={tempClothing.label} onChange={e => setTempClothing({...tempClothing, label: e.target.value})} /></InputGroup>
                 <InputGroup label="Prompt AI"><textarea className={`${baseInputClass} h-20`} value={tempClothing.prompt} onChange={e => setTempClothing({...tempClothing, prompt: e.target.value})} /></InputGroup>
                 <InputGroup label="Giới tính">
                    <select value={tempClothing.gender} onChange={e => setTempClothing({...tempClothing, gender: e.target.value as any})} className={baseInputClass}>
                       <option value="male">Nam</option>
                       <option value="female">Nữ</option>
                    </select>
                 </InputGroup>
              </div>
              <div className="flex justify-end gap-3 mt-8 border-t pt-4">
                 <button onClick={() => setShowClothingModal(false)} className="px-5 py-2 text-gray-500 font-bold">Hủy</button>
                 <button onClick={saveClothingItem} className="px-6 py-2 bg-brand-600 text-white font-bold rounded-xl shadow-lg">Lưu</button>
              </div>
           </div>
        </div>
      )}
