              <h3 className="text-xl font-bold mb-6 uppercase tracking-wider text-center">{editingColor ? 'Sửa' : 'Thêm'} màu {colorContext}</h3>
              <div className="space-y-4">
                 <InputGroup label="Tên nhãn"><input type="text" className={baseInputClass} value={tempColor.label} onChange={e => setTempColor({...tempColor, label: e.target.value})} /></InputGroup>
                 <InputGroup label="Màu sắc (HEX)"><input type="color" className="w-full h-12 p-1 rounded-xl" value={tempColor.hex} onChange={e => setTempColor({...tempColor, hex: e.target.value})} /></InputGroup>
