import React, { useState, useEffect } from 'react';
import { AppConfig } from '../types';
import { saveConfig, applyTheme } from '../services/configService';
import { saveAppConfigToCloud } from '../services/databaseService';

// Import split tab components
import AdminSystemTab from './AdminSystemTab';
import AdminClothingTab from './AdminClothingTab';
import AdminMakeupTab from './AdminMakeupTab';
import AdminSecurityTab from './AdminSecurityTab';

interface AdminDashboardProps {
  currentConfig: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [form, setForm] = useState<AppConfig>(currentConfig);
  const [activeTab, setActiveTab] = useState<'system' | 'clothing' | 'makeup_hair' | 'security'>('system');
  const [saveStatus, setSaveStatus] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    setIsSyncing(true);
    setSaveStatus('Đang kết nối Cloud...');

    if (!form.googleScriptUrl || !form.googleScriptUrl.startsWith('https://script.google.com')) {
        setIsSyncing(false);
        setSaveStatus('Lỗi URL');
        alert("Lỗi: URL Google Script không hợp lệ.");
        return;
    }

    saveConfig(form);
    onUpdateConfig(form);

    try {
        const success = await saveAppConfigToCloud(form);
        if (success) setSaveStatus('✔ Đã đồng bộ Cloud');
        else {
            setSaveStatus('⚠️ Đã lưu máy (Lỗi Cloud)');
            alert("Lưu cục bộ thành công nhưng lỗi đồng bộ Cloud.");
        }
    } catch (e) {
        setSaveStatus('❌ Lỗi mạng');
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 5000);
    }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col font-sans overflow-hidden">
      <header className="flex-none bg-white border-b border-gray-200 px-4 py-3 flex justify-between items-center shadow-sm z-20">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-gradient-to-br from-brand-500 to-brand-700 text-white rounded-lg flex items-center justify-center font-bold text-lg shadow-md">A</div>
          <div className="leading-tight">
            <h1 className="font-bold text-gray-800 text-base">Quản trị</h1>
            <p className="text-[10px] text-gray-400 hidden sm:block">ID Photo Booth Pro</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`text-sm font-bold transition-all ${saveStatus ? 'text-green-600' : 'opacity-0'}`}>{saveStatus}</span>
          <button onClick={onExit} className="px-3 py-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg text-sm font-bold transition flex items-center gap-1">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg> Thoát
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto scroll-smooth">
        <div className="max-w-7xl w-full mx-auto p-4 lg:p-6 grid grid-cols-1 lg:grid-cols-4 gap-6 lg:gap-8 items-start">
          <nav className="flex lg:flex-col gap-2 overflow-x-auto whitespace-nowrap pb-2 lg:pb-0 sticky top-0 z-10 bg-slate-50 lg:static -mx-4 px-4 lg:mx-0 lg:px-0 pt-2 lg:pt-0 scrollbar-hide">
            {[
              { id: 'system', label: 'Cấu hình hệ thống', icon: '⚙️' },
              { id: 'clothing', label: 'Trang phục', icon: '👔' },
              { id: 'makeup_hair', label: 'Làm đẹp & Tóc', icon: '💄' },
              { id: 'security', label: 'Bảo mật', icon: '🔒' }
