import React, { useState } from 'react';
import { AppConfig, ClothingItem } from '../types';
import { InputGroup, baseInputClass } from './AdminShared';

interface AdminClothingTabProps {
  form: AppConfig;
  setForm: React.Dispatch<React.SetStateAction<AppConfig>>;
}

const AdminClothingTab: React.FC<AdminClothingTabProps> = ({ form, setForm }) => {
  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  // Ensure options is always an array
  const clothingOptions = form.clothingOptions || [];

  const openAddClothing = () => {
    setEditingItem(null);
    setTempClothing({ id: `custom_${Date.now()}`, label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-blue-500' });
    setShowClothingModal(true);
  };

  const openEditClothing = (item: ClothingItem) => {
    setEditingItem(item);
    setTempClothing({ ...item });
    setShowClothingModal(true);
  };

  const saveClothingItem = () => {
    let newOptions = [...clothingOptions];
    if (editingItem) newOptions = newOptions.map(item => item.id === editingItem.id ? tempClothing : item);
    else newOptions.push(tempClothing);
    setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    setShowClothingModal(false);
  };

  const deleteClothingItem = (id: string) => {
    if (confirm('Bạn có chắc muốn xóa?')) {
      setForm(prev => ({ ...prev, clothingOptions: clothingOptions.filter(item => item.id !== id) }));
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold">Trang phục AI</h2>
        <button onClick={openAddClothing} className="px-4 py-2 bg-brand-600 text-white rounded-xl text-sm font-bold shadow-lg">Thêm mới</button>
      </div>
      <div className="grid grid-cols-1 gap-6">
        {['male', 'female'].map(gender => (
          <div key={gender} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="font-bold mb-4 uppercase text-xs tracking-widest text-slate-400">{gender === 'male' ? 'Nam' : 'Nữ'}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {clothingOptions.filter(c => c.gender === gender).map(item => (
                <div key={item.id} className="p-3 border rounded-xl flex items-center justify-between bg-slate-50">
                  <div className="flex items-center gap-3">
                    <span className="text-xl">{item.icon}</span>
                    <span className="text-sm font-bold">{item.label}</span>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => openEditClothing(item)} className="p-1 text-blue-600">✎</button>
                    <button onClick={() => deleteClothingItem(item.id)} className="p-1 text-red-600">✕</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {showClothingModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl animate-fadeIn">
              <h3 className="text-xl font-bold mb-6">{editingItem ? 'Sửa' : 'Thêm'} trang phục</h3>
              <div className="space-y-4">
                 <InputGroup label="Tên nhãn"><input type="text" className={baseInputClass} value={tempClothing.label} onChange={e => setTempClothing({...tempClothing, label: e.target.value})} /></InputGroup>
                 <InputGroup label="Prompt AI"><textarea className={`${baseInputClass} h-20`} value={tempClothing.prompt} onChange={e => setTempClothing({...tempClothing, prompt: e.target.value})} /></InputGroup>
                 <InputGroup label="Giới tính">
                    <select value={tempClothing.gender} onChange={e => setTempClothing({...tempClothing, gender: e.target.value as any})} className={baseInputClass}>
                       <option value="male">Nam</option>
                       <option value="female">Nữ</option>
                    </select>
                 </InputGroup>
              </div>
              <div className="flex justify-end gap-3 mt-8 border-t pt-4">
                 <button onClick={() => setShowClothingModal(false)} className="px-5 py-2 text-gray-500 font-bold">Hủy</button>
                 <button onClick={saveClothingItem} className="px-6 py-2 bg-brand-600 text-white font-bold rounded-xl shadow-lg">Lưu</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminClothingTab;

import React, { useState } from 'react';
import { AppConfig } from '../types';
import { InputGroup, baseInputClass } from './AdminShared';

interface AdminMakeupTabProps {
  form: AppConfig;
  setForm: React.Dispatch<React.SetStateAction<AppConfig>>;
}

const AdminMakeupTab: React.FC<AdminMakeupTabProps> = ({ form, setForm }) => {
  const [showColorModal, setShowColorModal] = useState(false);
  const [colorContext, setColorContext] = useState<'lipstick' | 'blush' | 'hair'>('lipstick');
  const [editingColor, setEditingColor] = useState<any | null>(null);
  const [tempColor, setTempColor] = useState({ id: '', label: '', hex: '#000000' });

  const openAddColor = (context: 'lipstick' | 'blush' | 'hair') => {
    setColorContext(context);
    setEditingColor(null);
    setTempColor({ id: `col_${Date.now()}`, label: '', hex: '#ef4444' });
    setShowColorModal(true);
  };

  const openEditColor = (context: 'lipstick' | 'blush' | 'hair', item: any) => {
    setColorContext(context);
    setEditingColor(item);
    setTempColor({ ...item });
    setShowColorModal(true);
  };

  const saveColorItem = () => {
    const listKey = colorContext === 'lipstick' ? 'lipstickOptions' : colorContext === 'blush' ? 'blushOptions' : 'hairColorOptions';
    let newList = [...((form[listKey] || []) as any[])];
    if (editingColor) newList = newList.map(item => item.id === editingColor.id ? tempColor : item);
    else newList.push(tempColor);
    setForm(prev => ({ ...prev, [listKey]: newList }));
    setShowColorModal(false);
  };

  const deleteColorItem = (context: 'lipstick' | 'blush' | 'hair', id: string) => {
    if (confirm('Xóa màu này?')) {
      const listKey = context === 'lipstick' ? 'lipstickOptions' : context === 'blush' ? 'blushOptions' : 'hairColorOptions';
      setForm(prev => ({ ...prev, [listKey]: ((prev[listKey] || []) as any[]).filter(item => item.id !== id) }));
    }
  };

  const sections = [
    { id: 'lipstick', label: 'Màu Môi (Lipsticks)', list: form.lipstickOptions || [] },
    { id: 'blush', label: 'Màu Má Hồng (Blush)', list: form.blushOptions || [] },
    { id: 'hair', label: 'Màu Tóc (Hair Colors)', list: form.hairColorOptions || [] }
  ];

  return (
    <div className="space-y-8 animate-fadeIn">
      {sections.map(section => (
        <div key={section.id} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
           <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-gray-800">{section.label}</h3>
              <button onClick={() => openAddColor(section.id as any)} className="text-xs bg-brand-600 text-white px-3 py-1.5 rounded-lg font-bold shadow-md hover:bg-brand-700">Thêm màu</button>
           </div>
           <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {section.list.map((item: any) => (
                 <div key={item.id} className="relative group p-3 border rounded-xl bg-slate-50 flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-full border shadow-sm" style={{ backgroundColor: item.hex }}></div>
                    <span className="text-[10px] font-bold text-slate-600 truncate w-full text-center">{item.label}</span>
                    <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                       <button onClick={() => openEditColor(section.id as any, item)} className="p-1 bg-white rounded shadow text-blue-500 hover:text-blue-700 text-[10px]">✎</button>
                       <button onClick={() => deleteColorItem(section.id as any, item.id)} className="p-1 bg-white rounded shadow text-red-500 hover:text-red-700 text-[10px]">✕</button>
                    </div>
                 </div>
              ))}
           </div>
        </div>
      ))}

      {showColorModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl animate-fadeIn">
              <h3 className="text-xl font-bold mb-6 uppercase tracking-wider text-center">{editingColor ? 'Sửa' : 'Thêm'} màu {colorContext}</h3>
              <div className="space-y-4">
                 <InputGroup label="Tên nhãn"><input type="text" className={baseInputClass} value={tempColor.label} onChange={e => setTempColor({...tempColor, label: e.target.value})} /></InputGroup>
                 <InputGroup label="Màu sắc (HEX)"><input type="color" className="w-full h-12 p-1 rounded-xl" value={tempColor.hex} onChange={e => setTempColor({...tempColor, hex: e.target.value})} /></InputGroup>
                 <InputGroup label="Mã HEX"><input type="text" className={baseInputClass} value={tempColor.hex} onChange={e => setTempColor({...tempColor, hex: e.target.value})} /></InputGroup>
              </div>
              <div className="flex justify-end gap-3 mt-8 border-t pt-4">
                 <button onClick={() => setShowColorModal(false)} className="px-5 py-2 text-gray-500 font-bold">Hủy</button>
                 <button onClick={saveColorItem} className="px-6 py-2 bg-brand-600 text-white font-bold rounded-xl shadow-lg">Xác nhận</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

