import React from 'react';
import { AppConfig, PhotoSize } from '../types';
import { baseInputClass } from './AdminShared';

interface AdminRulesTabProps {
  form: AppConfig;
  setForm: React.Dispatch<React.SetStateAction<AppConfig>>;
}

const AdminRulesTab: React.FC<AdminRulesTabProps> = ({ form, setForm }) => {
  const photoRules = form.photoRules || {};

  const handleRuleChange = (size: string, index: number, value: string) => {
    const newRules = { ...photoRules };
    if (!newRules[size]) newRules[size] = [];
    newRules[size][index] = value;
    setForm(prev => ({ ...prev, photoRules: newRules }));
  };

  const addRule = (size: string) => {
    const newRules = { ...photoRules };
    newRules[size] = [...(newRules[size] || []), 'Quy định mới...'];
    setForm(prev => ({ ...prev, photoRules: newRules }));
  };

  const removeRule = (size: string, index: number) => {
    const newRules = { ...photoRules };
    if (newRules[size]) {
      const updatedList = [...newRules[size]];
      updatedList.splice(index, 1);
      newRules[size] = updatedList;
      setForm(prev => ({ ...prev, photoRules: newRules }));
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {Object.values(PhotoSize).map(size => (
        <div key={size} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex justify-between items-center mb-4 border-b pb-2">
            <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">Quy định ảnh {size}</h3>
            <button onClick={() => addRule(size)} className="text-xs bg-brand-50 text-brand-600 px-3 py-1.5 rounded-lg font-bold hover:bg-brand-100">+ Thêm quy định</button>
          </div>
          <div className="space-y-3">
            {(photoRules[size] || []).map((rule, idx) => (
              <div key={idx} className="flex gap-2">
                <input 
                  type="text" 
                  value={rule} 
                  onChange={(e) => handleRuleChange(size, idx, e.target.value)} 
                  className={`${baseInputClass} text-sm py-2`} 
                />
                <button onClick={() => removeRule(size, idx)} className="text-red-400 hover:text-red-600 px-2">✕</button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default AdminRulesTab;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';
type ViewMode = 'slider' | 'sideBySide';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');
  const [viewMode, setViewMode] = useState<ViewMode>('slider');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: false,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction("AI đang xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      alert(err.message === 'AI_QUOTA_EXCEEDED' ? "HẾT LƯỢT AI. Thử lại sau." : "Lỗi xử lý AI.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng AI ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  const activeClothingOptions = (config.clothingOptions || []).filter(item => item.gender === genderTab);
  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-screen h-[100dvh] w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      <div className="w-full md:w-[400px] bg-white shadow-2xl z-20 flex flex-col h-[50dvh] md:h-full border-r border-gray-200">
        <div className="p-3 md:p-4 border-b border-gray-100 flex justify-between items-center shrink-0">
          <h2 className="text-lg md:text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">⚡</span> Chỉnh sửa
          </h2>
          <span className="text-[9px] md:text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">AI Generative</span>
        </div>

        <div className="px-3 pt-3 pb-1 md:px-4 md:pt-4 shrink-0">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto scrollbar-hide">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup'},
              {id: 'beauty', label: '4. Bộ lọc'}
            ].map((tab) => (
               <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 min-w-[65px] py-2 text-[10px] font-bold uppercase rounded-lg transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-brand-600 shadow-sm' : 'text-gray-500'}`}>{tab.label}</button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-5 bg-white scrollbar-hide">
          {activeTab === 'background' && (
            <div className="grid grid-cols-2 gap-3 animate-fadeIn">
               {(config.backgroundConfig || []).map(bg => (
                 <button key={bg.type} onClick={() => handleBgChange(bg.type)} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === bg.type ? 'border-brand-500 bg-brand-50' : 'border-slate-100 hover:bg-slate-50'}`}>
                   <div className="w-8 h-8 rounded-full border" style={{ backgroundColor: bg.hexColor }}></div>
                   <span className="text-[10px] font-bold">{bg.label}</span>
                 </button>
               ))}
               <button onClick={() => handleBgChange(BackgroundType.ORIGINAL)} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === BackgroundType.ORIGINAL ? 'border-brand-500 bg-brand-50' : 'border-slate-100 hover:bg-slate-50'}`}>
                 <div className="w-8 h-8 rounded-full bg-gray-300 flex items-center justify-center">📷</div>
                 <span className="text-[10px] font-bold">Ảnh Gốc</span>
               </button>
            </div>
          )}

          {activeTab === 'beauty' && (
            <div className="space-y-5 animate-fadeIn">
              <div className="space-y-4 px-1">
                 <div>
                    <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1"><span>Độ sáng</span><span>{settings.beauty.lighting}</span></div>
                    <input type="range" min="-50" max="50" step="5" value={settings.beauty.lighting} onChange={(e) => handleClientBeautyChange('lighting', Number(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg accent-brand-500" />
                 </div>
                 <div>
                    <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1"><span>Tương phản</span><span>{settings.beauty.contrast}</span></div>
                    <input type="range" min="-50" max="50" step="5" value={settings.beauty.contrast} onChange={(e) => handleClientBeautyChange('contrast', Number(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg accent-gray-600" />
                 </div>
              </div>
              <div className="grid grid-cols-4 gap-2">
                {SkinToneOptions.map(tone => (
                  <button key={tone.id} onClick={() => { handleClientBeautyChange('skinToneType', tone.id); if (settings.beauty.skinToneIntensity === 0) handleClientBeautyChange('skinToneIntensity', 30); }} className={`flex flex-col items-center gap-1 p-2 rounded-lg border ${settings.beauty.skinToneType === tone.id ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                    <div className="w-5 h-5 rounded-full border" style={{ backgroundColor: tone.color }}></div>
                    <span className="text-[8px] font-bold">{tone.label}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'makeup' && (
            <div className="space-y-6 animate-fadeIn">
              {/* Skin Smoothing */}
              <div>
                  <div className="flex justify-between text-[10px] font-bold text-gray-600 mb-1"><span>Làm mịn da (AI)</span><span>{settings.beauty.smoothSkin}%</span></div>
                  <input type="range" min="0" max="100" step="20" value={settings.beauty.smoothSkin} onChange={(e) => handleAiBeautyChange('smoothSkin', Number(e.target.value))} className="w-full h-1.5 bg-purple-100 rounded-lg accent-purple-600" />
              </div>

              {/* Lipstick Section */}
              <div className="space-y-3">
                 <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-600 uppercase">Màu Môi (AI)</span></div>
                 <div className="flex flex-wrap gap-2">
                    {(config.lipstickOptions || []).map(opt => (
                      <button key={opt.id} onClick={() => { handleAiBeautyChange('lipstickColor', opt.label); if(settings.beauty.lipstickIntensity === 0) handleAiBeautyChange('lipstickIntensity', 50); }} className={`w-6 h-6 rounded-full border-2 transition-all ${settings.beauty.lipstickColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white shadow-sm'}`} style={{ backgroundColor: opt.hex }} title={opt.label}></button>
                    ))}
                 </div>
                 <input type="range" min="0" max="100" step="20" value={settings.beauty.lipstickIntensity} onChange={(e) => handleAiBeautyChange('lipstickIntensity', Number(e.target.value))} className="w-full h-1 bg-pink-100 rounded-lg accent-pink-500" />
              </div>

              {/* Blush Section */}
              <div className="space-y-3">
                 <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-600 uppercase">Má Hồng (AI)</span></div>
                 <div className="flex flex-wrap gap-2">
                    {(config.blushOptions || []).map(opt => (
                      <button key={opt.id} onClick={() => { handleAiBeautyChange('blushColor', opt.label); if(settings.beauty.blushIntensity === 0) handleAiBeautyChange('blushIntensity', 30); }} className={`w-6 h-6 rounded-full border-2 transition-all ${settings.beauty.blushColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white shadow-sm'}`} style={{ backgroundColor: opt.hex }} title={opt.label}></button>
                    ))}
                 </div>
                 <input type="range" min="0" max="100" step="10" value={settings.beauty.blushIntensity} onChange={(e) => handleAiBeautyChange('blushIntensity', Number(e.target.value))} className="w-full h-1 bg-orange-50 rounded-lg accent-orange-300" />
              </div>

              {/* Hair Color Section */}
              <div className="space-y-3">
                 <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-600 uppercase">Màu Tóc (AI)</span></div>
                 <div className="flex flex-wrap gap-2">
                    {(config.hairColorOptions || []).map(opt => (
                      <button key={opt.id} onClick={() => { handleAiBeautyChange('hairColor', opt.label); if(opt.id !== 'original' && settings.beauty.hairVolume === 0) handleAiBeautyChange('hairVolume', 20); }} className={`w-6 h-6 rounded-full border-2 transition-all ${settings.beauty.hairColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white shadow-sm'} ${opt.id === 'original' ? 'bg-gradient-to-tr from-gray-200 via-gray-400 to-gray-200' : ''}`} style={opt.id !== 'original' ? { backgroundColor: opt.hex } : {}} title={opt.label}></button>
                    ))}
                 </div>
                 <div className="flex justify-between text-[9px] font-bold text-gray-400 uppercase"><span>Tóc thưa</span><span>Dày tóc</span></div>
                 <input type="range" min="0" max="100" step="20" value={settings.beauty.hairVolume} onChange={(e) => handleAiBeautyChange('hairVolume', Number(e.target.value))} className="w-full h-1 bg-slate-100 rounded-lg accent-slate-600" />
              </div>

              <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                <span className="text-xs font-bold text-gray-700">Sạch mụn</span>
                <input type="checkbox" checked={settings.beauty.removeBlemishes} onChange={() => handleAiBeautyChange('removeBlemishes', !settings.beauty.removeBlemishes)} className="w-4 h-4 accent-brand-600" />
              </div>
            </div>
          )}

          {activeTab === 'clothing' && (
            <div className="space-y-4 animate-fadeIn">
              <div className="flex p-1 bg-gray-100 rounded-xl">
                <button onClick={() => setGenderTab('male')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-all ${genderTab === 'male' ? 'bg-white text-gray-800' : 'text-gray-500'}`}>Nam</button>
                <button onClick={() => setGenderTab('female')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-all ${genderTab === 'female' ? 'bg-white text-gray-800' : 'text-gray-500'}`}>Nữ</button>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <button onClick={() => handleClothingClick('')} className={`p-2.5 border-2 rounded-xl text-center transition-all ${!settings.clothingPrompt ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                   <div className="text-xl mb-1">👕</div>
                   <div className="text-[10px] font-bold">Gốc</div>
                </button>
                {activeClothingOptions.map((item) => (
                  <button key={item.id} onClick={() => handleClothingClick(item.prompt)} className={`p-2.5 border-2 rounded-xl text-center transition-all ${settings.clothingPrompt === item.prompt ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                    <div className="text-xl mb-1">{item.icon}</div>
                    <div className="text-[10px] font-bold truncate">{item.label}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="p-3 md:p-4 border-t border-gray-200 bg-white space-y-2 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-xs shadow-md active:scale-95 disabled:opacity-50">✨ Áp dụng AI</button>
          )}
          <button onClick={handleFinish} disabled={isProcessing} className="w-full py-3 bg-brand-600 text-white rounded-xl font-bold text-sm shadow-lg active:scale-95 disabled:bg-gray-400">Hoàn tất & In</button>
          <button onClick={onRetake} disabled={isProcessing} className="w-full py-2 bg-slate-50 text-slate-500 rounded-xl font-bold text-xs border border-slate-200">Chụp lại</button>
        </div>
      </div>

      <div className="flex-1 bg-slate-200 relative flex items-center justify-center p-4 md:p-8 h-[50dvh] md:h-full">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/30 backdrop-blur-sm flex items-center justify-center">
            <div className="bg-white p-5 rounded-2xl shadow-2xl flex flex-col items-center">
              <div className="w-8 h-8 border-3 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
              <p className="text-brand-800 font-bold text-xs">{loadingAction}</p>
            </div>
          </div>
        )}
        <div ref={imageContainerRef} className="relative shadow-2xl rounded-sm border-2 border-white bg-white overflow-hidden max-h-full max-w-full"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '90%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-0.5 bg-white z-20 shadow-md" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-6 h-6 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-200">
              <div className="w-1 h-3 bg-brand-500 rounded-full"></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

