import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

// Sub-components
import EditorBackgroundTab from './EditorBackgroundTab';
import EditorClothingTab from './EditorClothingTab';
import EditorMakeupTab from './EditorMakeupTab';
import EditorFilterTab from './EditorFilterTab';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: false,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction("AI đang xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      alert(err.message === 'AI_QUOTA_EXCEEDED' ? "HẾT LƯỢT AI. Thử lại sau." : "Lỗi xử lý AI.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  // Handlers passed to sub-components
  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng AI ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen h-[100dvh] w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      <div className="w-full md:w-[400px] bg-white shadow-2xl z-20 flex flex-col h-[50dvh] md:h-full border-r border-gray-200">
        <div className="p-3 md:p-4 border-b border-gray-100 flex justify-between items-center shrink-0">
          <h2 className="text-lg md:text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">⚡</span> Chỉnh sửa
          </h2>
          <span className="text-[9px] md:text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">AI Generative</span>
        </div>

        <div className="px-3 pt-3 pb-1 md:px-4 md:pt-4 shrink-0">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto scrollbar-hide">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup'},
              {id: 'beauty', label: '4. Bộ lọc'}
            ].map((tab) => (
               <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 min-w-[65px] py-2 text-[10px] font-bold uppercase rounded-lg transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-brand-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{tab.label}</button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-5 bg-white scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        <div className="p-3 md:p-4 border-t border-gray-200 bg-white space-y-2 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-xs shadow-md active:scale-95 disabled:opacity-50">✨ Áp dụng AI</button>
          )}
          <button onClick={handleFinish} disabled={isProcessing} className="w-full py-3 bg-brand-600 text-white rounded-xl font-bold text-sm shadow-lg active:scale-95 disabled:bg-gray-400">Hoàn tất & In</button>
          <button onClick={onRetake} disabled={isProcessing} className="w-full py-2 bg-slate-50 text-slate-500 rounded-xl font-bold text-xs border border-slate-200">Chụp lại</button>
        </div>
      </div>

      <div className="flex-1 bg-slate-200 relative flex items-center justify-center p-4 md:p-8 h-[50dvh] md:h-full">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/30 backdrop-blur-sm flex items-center justify-center">
            <div className="bg-white p-5 rounded-2xl shadow-2xl flex flex-col items-center">
              <div className="w-8 h-8 border-3 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
              <p className="text-brand-800 font-bold text-xs">{loadingAction}</p>
            </div>
          </div>
        )}
        <div ref={imageContainerRef} className="relative shadow-2xl rounded-sm border-2 border-white bg-white overflow-hidden max-h-full max-w-full cursor-col-resize"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '90%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-0.5 bg-white z-20 shadow-md" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-6 h-6 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-200 cursor-grab active:cursor-grabbing">
              <div className="w-1 h-3 bg-brand-500 rounded-full"></div>
            </div>
          </div>

          <div className="absolute bottom-2 left-2 text-[8px] font-bold text-white bg-black/40 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Ảnh Gốc</div>
          <div className="absolute bottom-2 right-2 text-[8px] font-bold text-white bg-brand-600/60 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Đã xử lý</div>
        </div>
      </div>
    </div>
  );
};

