  const handleStart = () => {
    onStart({ size: selectedSize, background: selectedBg, quantity: quantity });
  };

  return (
    <div className="min-h-screen h-[100dvh] bg-gradient-to-br from-brand-50 to-indigo-50 flex items-center justify-center p-4 md:p-6 overflow-y-auto">
