              <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
              Chưa xác thực phiên (Project B)
           </div>
        </div>

        <div className="pt-4">
           <button 
             onClick={onAdminClick}
             className="text-xs font-bold text-slate-500 hover:text-white transition-colors uppercase tracking-widest flex items-center justify-center gap-2 mx-auto"
           >
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
             Đăng nhập quản trị
           </button>
        </div>
      </div>
    </div>
  );
};

export default UnauthorizedScreen;

import React, { useState, useEffect } from 'react';
import PhotoBooth from './components/PhotoBooth';
import AdminDashboard from './components/AdminDashboard';
import PhotoViewer from './components/PhotoViewer';
import UnauthorizedScreen from './components/UnauthorizedScreen';
import { AppConfig } from './types';
import { getConfig, applyTheme, updateFavicon, saveConfig } from './services/configService';
import { getAppConfigFromCloud } from './services/databaseService';

const App: React.FC = () => {
  const [isStarted, setIsStarted] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [isServiceAuthorized, setIsServiceAuthorized] = useState(false);
  const [config, setConfig] = useState<AppConfig>(getConfig());
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPass, setAdminPass] = useState('');

  // QR Viewer State
  const [viewerPhotoId, setViewerPhotoId] = useState<string | null>(null);

  // Key to force re-render of PhotoBooth when starting new
  const [boothKey, setBoothKey] = useState(0);

  // Load config and apply theme on mount
  useEffect(() => {
    // 1. Load Local
    const loadedConfig = getConfig();
    setConfig(loadedConfig);
    applyTheme(loadedConfig.themeColorHex);
    updateFavicon(loadedConfig.logoUrl);

    // 2. Auto-Fetch from Cloud if URL is configured
    const syncCloudConfig = async () => {
        if (loadedConfig.googleScriptUrl) {
            const cloudConfig = await getAppConfigFromCloud();
            if (cloudConfig) {
                setConfig(cloudConfig);
                saveConfig(cloudConfig);
                applyTheme(cloudConfig.themeColorHex);
                updateFavicon(cloudConfig.logoUrl);
            }
        }
    };
    syncCloudConfig();

    // 3. ACCESS CONTROL: Check for Service Token from Project B
    const params = new URLSearchParams(window.location.search);
    const token = params.get('token');
    const sessionId = params.get('sessionId');

    if (token || sessionId) {
      // In a real scenario, we would validate this token with Project B's API
      console.log(`Service Authorized via Project B. Token: ${token || sessionId}`);
      setIsServiceAuthorized(true);
    }

    // Check for QR Code Scan URL (?photoId=...)
    const photoId = params.get('photoId');
    if (photoId) {
      setViewerPhotoId(photoId);
    }
  }, []);

  const handleStart = () => {
    setBoothKey(prev => prev + 1);
    setIsStarted(true);
  };

  const handleHome = () => {
    setIsStarted(false);
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const targetPass = config.adminPassword || 'admin';
    if (adminPass === targetPass) {
      setIsAdminMode(true);
      setShowAdminLogin(false);
      setAdminPass('');
    } else {
      alert('Sai mật khẩu!');
    }
  };

  // --- VIEWER MODE (QR SCAN) ---
  if (viewerPhotoId) {
    return <PhotoViewer photoId={viewerPhotoId} config={config} />;
  }

  // --- ADMIN MODE ---
  if (isAdminMode) {
    return (
      <AdminDashboard 
        currentConfig={config}
        onUpdateConfig={(newConfig) => {
          setConfig(newConfig);
          applyTheme(newConfig.themeColorHex);
          updateFavicon(newConfig.logoUrl);
        }}
        onExit={() => setIsAdminMode(false)}
      />
    );
  }

  // --- ACCESS DENIED (NOT ADMIN AND NO SERVICE TOKEN) ---
  if (!isServiceAuthorized && !showAdminLogin && !isStarted) {
    return (
      <UnauthorizedScreen 
        config={config} 
        onAdminClick={() => setShowAdminLogin(true)} 
      />
    );
  }

  // --- SERVICE MODE (AUTHORIZED BY PROJECT B) ---
  if (!isStarted) {
    return (
      <div className="h-full w-full bg-gradient-to-br from-slate-900 via-slate-800 to-black flex items-center justify-center p-6 relative overflow-hidden font-sans">

        {/* Background Decorative Elements */}
        <div className="absolute top-0 left-0 w-96 h-96 bg-brand-600/20 rounded-full blur-[100px] -translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 right-0 w-[500px] h-[500px] bg-brand-600/10 rounded-full blur-[120px] translate-x-1/3 translate-y-1/3"></div>

        {/* Service Badge */}
        {isServiceAuthorized && (
          <div className="absolute top-6 right-6 flex items-center gap-2 bg-green-500/10 border border-green-500/30 px-4 py-2 rounded-full backdrop-blur-md z-50">
             <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
             <span className="text-[10px] font-black text-green-400 uppercase tracking-widest">Phiên làm việc hợp lệ</span>
          </div>
        )}

        {/* Home Screen UI */}
        <div className="text-center space-y-10 animate-fadeIn z-10 max-w-2xl w-full relative">

          <div className="relative w-40 h-40 mx-auto group">
             {config.logoUrl ? (
                <div className="relative w-full h-full bg-white rounded-3xl shadow-2xl flex items-center justify-center transform rotate-6 group-hover:rotate-0 transition-all duration-500 ease-out border-4 border-slate-50 overflow-hidden">
                   <img src={config.logoUrl} alt="Logo" className="w-full h-full object-contain p-2" />
                </div>
             ) : (
                <>
                  <div className="absolute inset-0 bg-brand-500 rounded-3xl blur-2xl opacity-20 group-hover:opacity-40 transition-opacity duration-500"></div>
                  <div className="relative w-full h-full bg-white rounded-3xl shadow-2xl flex items-center justify-center transform rotate-6 group-hover:rotate-0 transition-all duration-500 ease-out border-4 border-slate-50">
                      <svg className="w-24 h-24 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                  </div>
                </>
             )}
             <div className="absolute -top-4 -right-4 bg-yellow-400 text-yellow-900 text-xs font-black px-3 py-1 rounded-full shadow-lg transform rotate-12 group-hover:rotate-6 transition-transform z-10">
               Photomoments
             </div>
          </div>

          <div className="space-y-4">
            <h1 className="text-5xl md:text-6xl font-black text-white tracking-tight drop-shadow-lg">
              {config.welcomeTitle} <span className="text-brand-500">Pro</span>
            </h1>
            <p className="text-slate-400 text-lg md:text-xl max-w-lg mx-auto leading-relaxed">
              {config.welcomeSubtitle}
            </p>
          </div>

          <button 
            onClick={handleStart}
            className="group relative px-10 py-5 bg-gradient-to-r from-brand-600 to-brand-500 hover:from-brand-500 hover:to-brand-400 text-white rounded-2xl font-bold text-2xl shadow-[0_0_30px_rgba(var(--brand-600),0.4)] hover:shadow-[0_0_50px_rgba(var(--brand-600),0.6)] hover:-translate-y-1 transition-all duration-300 flex items-center gap-4 mx-auto overflow-hidden ring-4 ring-white/10"
          >
            <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-[shimmer_1.5s_infinite]"></div>
            <span>Bắt đầu chụp</span>
            <svg className="w-8 h-8 group-hover:translate-x-2 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
          </button>

          <div className="pt-12 grid grid-cols-3 gap-6 opacity-60">
             <div className="flex flex-col items-center gap-2">
                <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-green-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </div>
                <span className="text-xs font-mono text-slate-400">Google Gemini</span>
             </div>
             <div className="flex flex-col items-center gap-2">
                <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-blue-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"></path></svg>
                </div>
                <span className="text-xs font-mono text-slate-400">Biometric Check</span>
             </div>
             <div className="flex flex-col items-center gap-2">
                <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-purple-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                </div>
                <span className="text-xs font-mono text-slate-400">Smart Print</span>
             </div>
          </div>
        </div>

        <button 
          onClick={() => setShowAdminLogin(true)}
          className="absolute bottom-6 left-6 flex items-center gap-2 px-3 py-2 bg-white/10 hover:bg-white/20 text-slate-400 hover:text-white rounded-full transition-all backdrop-blur-sm border border-white/5 hover:border-white/20 group z-50"
        >
          <div className="w-6 h-6 rounded-full bg-slate-800 flex items-center justify-center text-slate-400 group-hover:text-white group-hover:bg-brand-600 transition-colors">
            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </div>
          <span className="text-xs font-bold uppercase tracking-wider">Admin</span>
        </button>

        {showAdminLogin && (
          <div className="absolute inset-0 bg-black/80 flex items-center justify-center z-50 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white p-6 rounded-2xl w-80 shadow-2xl transform scale-100 transition-all">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg text-gray-800">Đăng nhập Quản trị</h3>
                <button onClick={() => setShowAdminLogin(false)} className="text-gray-400 hover:text-gray-600">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
              </div>
              <form onSubmit={handleAdminLogin}>
                <div className="relative mb-4">
                  <span className="absolute left-3 top-2.5 text-gray-400">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                  </span>
                  <input type="password" autoFocus placeholder="Mật khẩu..." value={adminPass} onChange={(e) => setAdminPass(e.target.value)} className="w-full border border-gray-300 rounded-xl py-2.5 pl-10 pr-4 focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition" />
                </div>
                <button type="submit" className="w-full py-2.5 bg-brand-600 text-white rounded-xl font-bold hover:bg-brand-700 shadow-lg hover:shadow-xl transition-all transform active:scale-95">Đăng nhập</button>
              </form>
            </div>
          </div>
        )}

        <style>{`
          @keyframes shimmer { 100% { transform: translateX(100%); } }
          @keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
          .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        `}</style>
      </div>
    );
  }

  return (
    <div className="h-full w-full font-sans flex flex-col overflow-hidden">
      <PhotoBooth key={boothKey} config={config} onHome={handleHome} />
    </div>
  );
};

export default App;
